package kr.signal.mealcaremacro;
import android.accessibilityservice.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.format.*;import java.util.*;import java.util.regex.*;
public class MacroService extends AccessibilityService {
 static MacroService instance; boolean running=false; Handler h=new Handler(Looper.getMainLooper()); String pkg; LocalDate start,pending; boolean preview; Set<String> seen=new HashSet<>(),booked=new HashSet<>(); String state=""; long due,deadline; int idle,scrolls,success,skips; String lastSig="",lastDump=""; Set<String> closedCards=new HashSet<>(); WindowManager wm; LinearLayout overlay; TextView info;
 static final Pattern FULL=Pattern.compile("(?<!\\d)(20\\d{2})(?:[.\\-/년\\s]+)(\\d{1,2})(?:[.\\-/월\\s]+)(\\d{1,2})(?!\\d)|(?<!\\d)(20\\d{2})(\\d{2})(\\d{2})(?!\\d)");
 static final Pattern SHORT=Pattern.compile("(?<!\\d)(\\d{1,2})(?:[.\\-/월]\\s*|\\s+)(\\d{1,2})(?!\\d)(?=\\s*(?:[.()일월화수목금토]|픽업|$))");
 static final Pattern PICKUP=Pattern.compile("(?<!\\d)(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})(?:\\s*일)?\\s*(?:\\([월화수목금토일]\\))?\\s*픽업");
 static final String PRODUCT="헬시팩(사내식당-석식용)",TAB="석식(사내식당)";
 static String norm(String s){return s==null?"":s.replaceAll("\\s+","").replace('–','-').replace('−','-');}
 static class Item{AccessibilityNodeInfo node;String text,raw;Rect r=new Rect();Item(AccessibilityNodeInfo n,String s){node=n;raw=s;text=norm(s);n.getBoundsInScreen(r);}}
 LocalDate parse(String s){Matcher m=FULL.matcher(s);try{if(m.find())return LocalDate.of(Integer.parseInt(m.group(1)!=null?m.group(1):m.group(4)),Integer.parseInt(m.group(2)!=null?m.group(2):m.group(5)),Integer.parseInt(m.group(3)!=null?m.group(3):m.group(6)));m=SHORT.matcher(s);if(m.find()){LocalDate now=LocalDate.now();LocalDate d=LocalDate.of(now.getYear(),Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)));if(d.isBefore(now.minusMonths(6)))d=d.plusYears(1);if(d.isAfter(now.plusMonths(6)))d=d.minusYears(1);return d;}}catch(Exception ignored){}return null;}
 @Override public void onServiceConnected(){instance=this;}
 @Override public void onAccessibilityEvent(AccessibilityEvent e){}
 @Override public void onInterrupt(){stop("접근성 중단");}
 @Override public void onDestroy(){stop("서비스 종료");instance=null;super.onDestroy();}
 SharedPreferences prefs(){return getSharedPreferences("run",0);}
 void log(String s){trace("LOG "+s);String old=prefs().getString("log","");String line=LocalTime.now().withNano(0)+" "+s;String all=line+"\n"+old;prefs().edit().putString("log",all.substring(0,Math.min(20000,all.length()))).putString("status",s).apply();if(info!=null)info.setText("예약 "+success+" · "+s);}
 void begin(String p,LocalDate d,boolean dry){if(running)return;pkg=p;start=d;preview=dry;seen.clear();closedCards.clear();lastDump="";booked=new HashSet<>(prefs().getStringSet("booked",Collections.emptySet()));seen.addAll(booked);pending=null;idle=scrolls=success=skips=0;lastSig="";state="OPEN";running=true;deadline=SystemClock.uptimeMillis()+20*60*1000;due=SystemClock.uptimeMillis()+1600;show();trace("\n=== v1.0.3 RUN "+LocalDateTime.now()+" package="+p+" start="+d+" preview="+dry+" ===");log("시작 "+d+(dry?" (탐색만)":""));h.post(tick);}
 void stop(String reason){if(!running)return;running=false;h.removeCallbacks(tick);if(pending!=null&&("RESULT".equals(state)||"CONFIRM".equals(state)))reason+=" · "+pending+" 결과 미확인, 주문 내역 확인 필요";log(reason+" / 완료 "+success+"건");if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;info=null;}}
 void show(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);overlay=new LinearLayout(this);overlay.setOrientation(0);overlay.setGravity(Gravity.CENTER_VERTICAL);overlay.setPadding(12,4,8,4);overlay.setBackgroundColor(0xee182b21);info=new TextView(this);info.setTextColor(Color.WHITE);info.setMaxLines(2);info.setTextSize(12);overlay.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button b=new Button(this);b.setText("중지");b.setOnClickListener(v->stop("사용자 중지"));overlay.addView(b);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(getResources().getDisplayMetrics().widthPixels*4/5,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;try{wm.addView(overlay,lp);}catch(Exception e){overlay=null;info=null;}}
 void walk(AccessibilityNodeInfo n,List<Item> out,int depth){if(n==null||depth>40||out.size()>1500)return;if(n.isVisibleToUser()&&!n.isPassword()){if(n.getText()!=null)out.add(new Item(n,n.getText().toString()));if(n.getContentDescription()!=null&&!Objects.equals(n.getText(),n.getContentDescription()))out.add(new Item(n,n.getContentDescription().toString()));}for(int i=0;i<n.getChildCount();i++)walk(n.getChild(i),out,depth+1);}
 Item exact(List<Item>a,String t){for(Item i:a)if(i.text.equals(t)&&!i.r.isEmpty())return i;return null;}
 boolean contains(List<Item>a,String t){for(Item i:a)if(i.text.contains(t))return true;return false;}
 boolean tap(Item i){if(i==null||!i.node.isEnabled()||i.r.isEmpty())return false;AccessibilityNodeInfo n=i.node;for(int k=0;n!=null&&k<5;k++,n=n.getParent())if(n.isClickable()&&n.isEnabled()&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;Rect r=i.r;Path path=new Path();path.moveTo(r.exactCenterX(),r.exactCenterY());return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,80)).build(),null,null);}
 void next(String s,long ms){trace("STATE "+state+" -> "+s+" wait="+ms+"ms");state=s;idle=0;due=SystemClock.uptimeMillis()+ms;}
 boolean move(Item i,String s){trace("CLICK "+(i==null?"null":describe(i))+" -> "+s);if(tap(i)){next(s,1050);return true;}return false;}
 void waitMore(){if(idle==0||idle==7||idle==14)trace("WAIT state="+state+" attempt="+(idle+1)+" pending="+pending);if(++idle>14){stop("화면 인식 시간 초과: "+state);return;}due=SystemClock.uptimeMillis()+500;}
 boolean swipe(boolean down){trace("SWIPE "+(down?"DOWN":"UP")+" state="+state+" count="+scrolls);int w=getResources().getDisplayMetrics().widthPixels,hh=getResources().getDisplayMetrics().heightPixels;Path p=new Path();p.moveTo(w*.50f,hh*(down?.77f:.30f));p.lineTo(w*.50f,hh*(down?.30f:.77f));return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,440)).build(),null,null);}
 String sig(List<Item>a){StringBuilder b=new StringBuilder();for(Item i:a)if(i.text.contains("픽업")||i.text.contains("헬시팩")||i.text.contains("샐러드")||i.text.contains("투고서비스"))b.append(i.text).append('@').append(i.r.top/30).append(';');return b.toString();}
 LocalDate detailDate(List<Item>a){for(Item i:a)if(i.text.contains("픽업날짜")||i.text.equals("픽업일")||i.text.equals("픽업일자")){ArrayList<Item> row=new ArrayList<>();row.add(i);for(Item j:a)if(j!=i&&Math.abs(j.r.centerY()-i.r.centerY())<Math.max(35,i.r.height()))row.add(j);for(Item j:row){LocalDate d=parseFull(j.raw);if(d!=null)return d;}row.sort(Comparator.comparingInt(j->j.r.left));StringBuilder b=new StringBuilder();for(Item j:row)b.append(j.raw).append(" ");LocalDate full=parseFull(b.toString());if(full!=null)return full;for(Item j:row){LocalDate d=parseDetailShort(j.raw);if(d!=null)return d;}return parseDetailShort(b.toString());}return null;}
 LocalDate parseDetailShort(String s){Matcher m=SHORT.matcher(s);if(!m.find())return null;try{int month=Integer.parseInt(m.group(1)),day=Integer.parseInt(m.group(2));if(pending!=null&&pending.getMonthValue()==month&&pending.getDayOfMonth()==day)return pending;return parse(s);}catch(Exception e){return null;}}
 LocalDate parseFull(String s){return FULL.matcher(s).find()?parse(s):null;}
 boolean oneQuantity(List<Item>a){Item label=exact(a,"수량");if(label==null){for(Item i:a)if(i.text.matches("수량[:：]?1"))return true;return false;}for(Item i:a){if(Math.abs(i.r.centerY()-label.r.centerY())>Math.max(35,label.r.height()))continue;if(i.text.equals("1")||i.text.matches("수량[:：]?1")||i.text.matches("[−–-]?1[+]"))return true;}return label.text.matches("수량[:：]?1");}
 Item reserveButton(List<Item>a){Item i=exact(a,"예약하기");if(i!=null)return i;for(Item j:a)if(j.text.matches("예약하기(?:버튼)?")&&j.node.isEnabled()&&!j.r.isEmpty())return j;return null;}
 boolean directTap(Item i){if(i==null||!i.node.isEnabled()||i.r.isEmpty())return false;Rect r=i.r;Path p=new Path();p.moveTo(r.exactCenterX(),r.exactCenterY());return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,100)).build(),new GestureResultCallback(){@Override public void onCompleted(GestureDescription g){trace("RESERVE gesture completed");}@Override public void onCancelled(GestureDescription g){trace("RESERVE gesture cancelled");stop("예약 터치 취소");}},h);}
 String diagnostics(List<Item>a){StringBuilder b=new StringBuilder();for(Item i:a){if(i.text.contains("픽업")||i.text.contains("예약")||i.text.contains("수량")||i.text.matches("[0-9. /년월일()-]+")){if(b.length()>700)break;b.append("[").append(i.raw).append("] ");}}return b.toString();}
 boolean sameColumn(Item a,Item b){int mid=getResources().getDisplayMetrics().widthPixels/2;return (a.r.centerX()<mid)==(b.r.centerX()<mid);}
 boolean isProduct(Item i){return i.text.contains("사내식당")&&!i.text.equals(TAB)&&(i.text.contains("헬시팩")||i.text.contains("샐러드")||i.text.contains("투고서비스"));}
 Item pickupBadge(List<Item>a,Item product){Item best=null;int dist=Integer.MAX_VALUE;int max=getResources().getDisplayMetrics().heightPixels*48/100;
 for(Item i:a){if(!PICKUP.matcher(norm(i.raw)).find()||!sameColumn(i,product)||i.r.isEmpty())continue;
 int dy=product.r.top-i.r.bottom;if(dy<0||dy>max)continue;boolean blocked=false;
 for(Item other:a)if(other!=product&&isProduct(other)&&sameColumn(other,product)&&other.r.centerY()>i.r.bottom&&other.r.centerY()<product.r.top-8){blocked=true;break;}
 if(!blocked&&dy<dist){best=i;dist=dy;}}
 return best;}
 boolean closed(List<Item>a,Item product,Item badge){if(!product.node.isEnabled())return true;for(Item i:a)if(i.text.equalsIgnoreCase("CLOSED")&&sameColumn(i,product)&&i.r.centerY()>badge.r.top-20&&i.r.centerY()<product.r.bottom)return true;return false;}
 LocalDate cardDate(List<Item>a,Item product){if(product.text.contains("픽업")&&PICKUP.matcher(product.text).find())return parse(product.raw);Item badge=pickupBadge(a,product);return badge==null?null:parse(badge.raw);}
 String describe(Item i){return "'"+i.raw.replace('\n',' ').replace('\r',' ')+"' bounds="+i.r.toShortString()+" class="+i.node.getClassName()+" id="+i.node.getViewIdResourceName()+" enabled="+i.node.isEnabled()+" clickable="+i.node.isClickable();}
 File traceFile(){return new File(getFilesDir(),"mealcare-diagnostic.txt");}
 void trace(String line){try{File f=traceFile();if(f.length()>1500000){File prev=new File(getFilesDir(),"mealcare-diagnostic-prev.txt");if(prev.exists())prev.delete();f.renameTo(prev);}try(FileOutputStream out=new FileOutputStream(f,true)){out.write((LocalTime.now().withNano(0)+" ["+state+"] "+line+"\n").getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
 void snapshot(List<Item>a,AccessibilityNodeInfo root){StringBuilder b=new StringBuilder();b.append("WINDOW ").append(root.getClassName()).append(" nodes=").append(a.size()).append('\n');int count=0;for(Item i:a){if(++count>250){b.append("... truncated\n");break;}b.append(describe(i)).append('\n');}String dump=b.toString();String key=state+"|"+dump;if(!key.equals(lastDump)){lastDump=key;trace(dump);}}
 void record(LocalDate d,boolean ok){seen.add(d.toString());if(ok){booked.add(d.toString());prefs().edit().putStringSet("booked",new HashSet<>(booked)).commit();success++;log(d+" 예약 완료");}else{skips++;log(d+" "+(preview?"탐색 확인":"예약 제외"));}}
 void backToList(){pending=null;performGlobalAction(GLOBAL_ACTION_BACK);next("RETURN",1100);}
 final Runnable tick=new Runnable(){public void run(){if(!running)return;try{if(SystemClock.uptimeMillis()>deadline){stop("실행 제한 도달");return;}if(SystemClock.uptimeMillis()>=due)step();}catch(Exception e){trace(android.util.Log.getStackTraceString(e));stop("오류: "+e.getClass().getSimpleName());}if(running)h.postDelayed(this,350);}};
 void step(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null||!pkg.equals(String.valueOf(root.getPackageName()))){if(idle==0)trace("WAIT target window: "+(root==null?"null":root.getPackageName()));waitMore();return;}List<Item>a=new ArrayList<>();walk(root,a,0);snapshot(a,root);
 if("RESULT".equals(state)){if(contains(a,"예약이완료되었습니다")||contains(a,"예약이완료")){record(pending,true);pending=null;Item ok=exact(a,"확인");if(!move(ok,"RETURN"))stop("예약 완료, 확인 버튼 인식 실패");return;}if(contains(a,"이미예약")||contains(a,"이미신청")){record(pending,false);pending=null;if(!move(exact(a,"확인"),"RETURN"))backToList();return;}waitMore();return;}
 if("DETAIL".equals(state)){if(!contains(a,"상세메뉴")){if(idle==0)trace("DETAIL waiting for title");waitMore();return;}if(!contains(a,PRODUCT)){stop("다른 상품 상세 화면");return;}LocalDate d=detailDate(a);if(d==null){if(idle==0)log("상세 날짜 인식 실패: "+diagnostics(a));waitMore();return;}trace("DETAIL expected="+pending+" actual="+d+" start="+start);if(pending==null||!pending.equals(d)){stop("목록/상세 날짜 불일치: "+pending+" / "+d);return;}if(d.isBefore(start)||seen.contains(d.toString())){backToList();return;}
 Item reserve=reserveButton(a);if(contains(a,"예약불가")||contains(a,"예약마감")||contains(a,"이미예약")||contains(a,"CLOSED")||(reserve!=null&&!reserve.node.isEnabled())){record(d,false);backToList();return;}
 if(preview){record(d,false);backToList();return;}if(reserve==null){if(idle==0)log("예약 버튼 인식 실패: "+diagnostics(a));waitMore();return;}if(!oneQuantity(a)){stop("수량 1 확인 실패: "+diagnostics(a));return;}trace("RESERVE "+describe(reserve)+" quantity verified");if(!directTap(reserve)){stop("예약 버튼 터치 실패: "+diagnostics(a));return;}next("RESULT",1600);log(d+" 예약 버튼 터치");return;}
 if(contains(a,"상세메뉴")||contains(a,"예약이완료되었습니다")){stop("예상하지 못한 상세/완료 화면");return;}
 Item tab=exact(a,TAB);if("OPEN".equals(state)||"RETURN".equals(state)){if(tab!=null){if(move(tab,"TOP")){lastSig="";scrolls=0;return;}}Item smart=exact(a,"스마트오더");if(move(smart,"OPEN"))return;waitMore();return;}
 if(tab==null){waitMore();return;}if("TOP".equals(state)){String now=sig(a);if(now.equals(lastSig)||scrolls>=35){lastSig="";scrolls=0;next("SCAN",400);return;}lastSig=now;scrolls++;swipe(false);due=SystemClock.uptimeMillis()+850;return;}
 if("SCAN".equals(state)){ArrayList<Item> products=new ArrayList<>();for(Item i:a)if(i.text.equals(PRODUCT)||i.text.startsWith(PRODUCT+"픽업"))products.add(i);products.sort(Comparator.comparingInt(i->i.r.top));for(Item i:products){Item badge=pickupBadge(a,i);LocalDate d=cardDate(a,i);trace("CARD "+describe(i)+" badge="+(badge==null?"none":describe(badge))+" parsed="+d);
 if(d==null){trace("SKIP no matching date above product");continue;}if(d.isBefore(start)||seen.contains(d.toString())){trace("SKIP "+d+" before start or already handled");continue;}
 if(badge!=null&&closed(a,i,badge)){String key=d+"|"+i.r.toShortString();if(closedCards.add(key))trace("SKIP CLOSED "+d);continue;}
 pending=d;if(move(i,"DETAIL"))return;stop("상품 클릭 실패: "+d);return;}
 String now=sig(a);if(now.isEmpty()){if(idle==0)trace("No list signature; visible nodes="+a.size());waitMore();return;}if(now.equals(lastSig)){if(++idle>=3){stop("현재 목록 탐색 종료 · 탐색/제외 "+skips+"건");return;}}else idle=0;if(++scrolls>70){stop("스크롤 제한 도달");return;}lastSig=now;swipe(true);due=SystemClock.uptimeMillis()+850;return;}
 waitMore();
 }
}